import sys
import inspect
import datetime
import six
from IQCommon import pandas as pd
from functools import wraps
from dateutil.parser import parse as parse_date
from IQData import const
from IQData.engine import engine
from IQData import utils
from IQData.utils import exception
from IQData.utils.i18n import get_local_text as _
from IQCommon.exception import get_traceback_message
from IQCommon.logger import system_log
class ArgumentChecker(object):
    __doc__ = '\n    用于参数校验的类\n    '
    def __init__(self, arg_name):
        self._arg_name = arg_name
        self._rules = []
    def verify(self, func_name, value):
        for r in self._rules:
            r(func_name, value)
    @property
    def arg_name(self):
        return self._arg_name
    def is_instance(self, types):
        def check_is_instance(func_name, value):
            if (not isinstance(value, types)):
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a value of type {}, got {} (type: {})').format(func_name, self._arg_name, types, value, type(value)))
        self._rules.append(check_is_instance)
        return self
    def is_valid_asset(self):
        self._rules.append(self._is_valid_asset)
        return self
    def is_valid_stock(self):
        self._rules.append(self._is_valid_stock)
        return self
    def is_valid_future(self):
        self._rules.append(self._is_valid_future)
        return self
    def is_number(self):
        self._rules.append(self._is_number)
        return self
    def is_in(self, valid_values, ignore_none=True):
        def check_is_in(func_name, value):
            if (ignore_none and value is None):
                return None
            elif (value not in valid_values):
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, valid: {}, got {} (type: {})').format(func_name, self._arg_name, repr(valid_values), value, type(value)))
            else:
                return None
        self._rules.append(check_is_in)
        return self
    def are_valid_fields(self, valid_fields, ignore_none=True):
        valid_fields = set(valid_fields)
        def check_are_valid_fields(func_name, fields):
            if isinstance(fields, six.string_types):
                if (fields not in valid_fields):
                    raise exception.IQInvalidArgument(_('function {}: invalid {} argument, valid fields are {}, got {} (type: {})').format(func_name, self._arg_name, repr(valid_fields), fields, type(fields)))
                return None
            elif (fields is None and ignore_none):
                return None
            elif isinstance(fields, list):
                invalid_fields = [field for field in fields if field not in valid_fields]
                if invalid_fields:
                    raise exception.IQInvalidArgument(_('function {}: invalid field {}, valid fields are {}, got {} (type: {})').format(func_name, invalid_fields, repr(valid_fields), fields, type(fields)))
                return None
            else:
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a string or a list of string, got {} (type: {})').format(func_name, self._arg_name, repr(fields), type(fields)))
        self._rules.append(check_are_valid_fields)
        return self
    def are_valid_assets(self):
        self._rules.append(self._are_valid_assets)
        return self
    def is_valid_date(self, ignore_none=True):
        def check_is_valid_date(func_name, value):
            if (ignore_none and value is None):
                return None
            elif isinstance(value, (datetime.date, pd.Timestamp)):
                return None
            elif isinstance(value, int):
                value = str(value)
            if isinstance(value, six.string_types):
                try:
                    parse_date(value)
                except ValueError:
                    system_log.error(get_traceback_message())
                    raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a valid date, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
            else:
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a valid date, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
        self._rules.append(check_is_valid_date)
        return self
    def compare(self, operator, value_compared):
        if isinstance(operator, const.CompareEnum):
            (compare_str, operator) = operator.value
        elif callable(operator):
            compare_str = operator.__name__
        else:
            return None
        def check_compare(func_name, value):
            if (not operator(value, value_compared)):
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a value {} {}, got {} (type: {})').format(func_name, self._arg_name, compare_str, value_compared, value, type(value)))
        self._rules.append(check_compare)
        return self
    def is_valid_interval(self):
        self._rules.append(self._is_valid_interval)
        return self
    def is_valid_quarter(self):
        self._rules.append(self._is_valid_quarter)
        return self
    def are_valid_query_entities(self):
        self._rules.append(self._are_valid_query_entities)
        return self
    def is_valid_frequency(self):
        self._rules.append(self._is_valid_frequency)
        return self
    def is_valid_search_direction(self):
        self._rules.append(self._is_valid_search_direction)
        return self
    def raise_invalid_asset_error(self, func_name, arg_name, value):
        raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a valid asset/symbol, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
    def raise_not_valid_stock_error(self, func_name, arg_name, value):
        raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a valid stock asset/symbol, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
    def raise_not_valid_future_error(self, func_name, arg_name, value):
        raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a valid future asset/symbol, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
    def _is_number(self, func_name, value):
        try:
            float(value)
        except (ValueError, TypeError):
            system_log.error(get_traceback_message())
            raise exception.IQInvalidArgument(_('function {}: invalid {} argument, expect a number, got {} (type: {})').format(func_name, self._arg_name, value, type(value)))
    def _is_valid_interval(self, func_name, value):
        valid = (isinstance(value, six.string_types) and value[-1] in {'d', 'q', 'm', 'y'})
        if valid:
            pass
        try:
            valid = (int(value[:-1]) > 0)
        except (ValueError, TypeError):
            system_log.error(get_traceback_message())
            valid = False
        if (not valid):
            raise exception.IQInvalidArgument(_("function {}: invalid {} argument, interval should be in form of '1d', '3m', '4q', '2y', got {} (type: {})").format(func_name, self.arg_name, value, type(value)))
    def _is_valid_quarter(self, func_name, value):
        if (value is None):
            valid = True
        else:
            valid = (isinstance(value, six.string_types) and value[-2] == 'q')
            if valid:
                pass
            try:
                (1990 <= int(value[:-2]) and 9999)
                valid = (1 <= int(value[-1]) and 1 <= int(value[-1]))
            except (ValueError, TypeError):
                system_log.error(get_traceback_message())
                valid = False
        if (not valid):
            raise exception.IQInvalidArgument(_("function {}: invalid {} argument, quarter should be in form of '2018q3', got {} (type: {})").format(func_name, self.arg_name, value, type(value)))
    def _are_valid_query_entities(self, func_name, entities):
        from sqlalchemy.orm.attributes import InstrumentedAttribute
        for e in entities:
            if (not isinstance(e, InstrumentedAttribute)):
                raise exception.IQInvalidArgument(_('function {}: invalid {} argument, should be entity like Fundamentals.balance_sheet.total_equity, got {} (type: {})').format(func_name, self.arg_name, e, type(e)))
    def _is_valid_frequency(self, func_name, value):
        valid = isinstance(value, six.string_types)
        if valid:
            if (value[-1] in ('d', 'm')):
                try:
                    valid = (int(value[:-1]) > 0)
                except (ValueError, TypeError):
                    system_log.error(get_traceback_message())
                    valid = False
            elif (value == 'tick'):
                pass
            else:
                valid = False
        if (not valid):
            raise exception.IQInvalidArgument(_("function {}: invalid {} argument, frequency should be in form of '1m', '5m', '1d', 'tick' got {} (type: {})").format(func_name, self.arg_name, value, type(value)))
    def _is_valid_search_direction(self, func_name, value):
        valid = isinstance(value, six.integer_types)
        if valid:
            if (value in (1, 2)):
                pass
            else:
                valid = False
        if (not valid):
            raise exception.IQInvalidArgument(_('function {}: invalid {} argument, search_direction should be in1, 2 got {} (type: {})').format(func_name, self.arg_name, value, type(value)))
def verify_arg(arg_name):
    return ArgumentChecker(arg_name)
def apply_rules(*rules):
    def decorator(func):
        @wraps(func)
        def api_rule_check_wrapper(*args, **kwargs):
            try:
                return func(*args, **kwargs)
                return None
            except exception:
                system_log.error(get_traceback_message())
                raise
            except Exception as e:
                system_log.error(get_traceback_message())
                exc_info = sys.exc_info()
                (t, v, tb) = exc_info
                try:
                    call_args = inspect.getcallargs(utils.get_original_function(func), *args, **kwargs)
                except TypeError as e:
                    system_log.error(get_traceback_message())
                    six.reraise(exception.IQTypeError, exception.IQTypeError(*e.args), tb)
                try:
                    for r in rules:
                        r.verify(func.__name__, call_args[r.arg_name])
                except exception as e:
                    system_log.error(get_traceback_message())
                    six.reraise(exception.IQInvalidArgument, e, tb)
                if (getattr(e, const.EXC_EXT_NAME, const.ExcType.NOTSET) == const.ExcType.NOTSET):
                    exception.system_exc(e)
                raise
        api_rule_check_wrapper._rq_exception_checked = True
        return api_rule_check_wrapper
    return decorator
